// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testFuzz_property(uint8 times) public {
        vm.assume(times >= 1 && times <= 10);
        address player = makeAddr("player");
        uint expectedPot = 0;
        for (uint i = 0; i < times; i++) {
            vm.deal(player, 10 ether);
            vm.prank(player);
            c.play{value: 10}();
            expectedPot = (c.pot() == 0) ? 0 : expectedPot + 10;
        }
        uint actualPot = c.pot();
        assertEq(actualPot, expectedPot, "pot must equal sum of tickets minus reset pays");
    }
}
